<link href="https://fonts.googleapis.com/css2?family=Press+Start+2P&display=swap" rel="stylesheet">
<style>
  html,body{margin:0;padding:0;height:100%;overflow:hidden;background:#000;
    font-family:'Press Start 2P',monospace;user-select:none;-webkit-user-select:none;}
  #wrap{position:fixed;inset:0;display:flex;align-items:center;justify-content:center;background:#223;}
  canvas{image-rendering:pixelated;cursor:crosshair;box-shadow:0 0 0 4px #111,0 0 40px #000;}
</style>
