<body>
<div id="wrap"><canvas id="c"></canvas></div>
<script>
"use strict";
/* Balloon Pop '95 - single-file archery. Aim with mouse, hold to draw, release to shoot. */

const cv = document.getElementById('c');
const ctx = cv.getContext('2d');
const W = 960, H = 540;
cv.width = W; cv.height = H;

/* ---------- audio (WebAudio, no assets) ---------- */
let AC = null;
function audio(){ if(!AC){ try{ AC = new (window.AudioContext||window.webkitAudioContext)(); }catch(e){} } if(AC && AC.state==='suspended') AC.resume(); return AC; }
function beep(freq, dur, type, vol, slideTo){
  const ac = audio(); if(!ac) return;
  const t = ac.currentTime;
  const o = ac.createOscillator(), g = ac.createGain();
  o.type = type||'square';
  o.frequency.setValueAtTime(freq, t);
  if(slideTo) o.frequency.exponentialRampToValueAtTime(Math.max(30,slideTo), t+dur);
  g.gain.setValueAtTime(vol||0.15, t);
  g.gain.exponentialRampToValueAtTime(0.0001, t+dur);
  o.connect(g); g.connect(ac.destination);
  o.start(t); o.stop(t+dur+0.02);
}
function noise(dur, vol, hp){
  const ac = audio(); if(!ac) return;
  const t = ac.currentTime;
  const len = Math.floor(ac.sampleRate*dur);
  const buf = ac.createBuffer(1, len, ac.sampleRate);
  const d = buf.getChannelData(0);
  for(let i=0;i<len;i++) d[i] = (Math.random()*2-1)*(1-i/len);
  const s = ac.createBufferSource(); s.buffer = buf;
  const f = ac.createBiquadFilter(); f.type='highpass'; f.frequency.value = hp||800;
  const g = ac.createGain(); g.gain.value = vol||0.2;
  s.connect(f); f.connect(g); g.connect(ac.destination);
  s.start(t);
}
const sfx = {
  draw(){ beep(180,0.08,'sawtooth',0.05,320); },
  shoot(){ noise(0.12,0.25,1500); beep(220,0.1,'square',0.12,60); },
  pop(){ noise(0.09,0.3,600); beep(660,0.09,'square',0.18,1400); },
  miss(){ beep(140,0.15,'triangle',0.1,80); },
  win(){ [523,659,784,1046].forEach((f,i)=>setTimeout(()=>beep(f,0.18,'square',0.15),i*110)); },
  lose(){ [392,330,262,196].forEach((f,i)=>setTimeout(()=>beep(f,0.22,'sawtooth',0.12),i*160)); }
};

/* ---------- state ---------- */
const STATE = { MENU:0, PLAY:1, WIN:2, LOSE:3 };
let state = STATE.MENU;
let score = 0, shots = 0, maxShots = 15, target = 12;
let balloons = [], arrows = [], parts = [], floats = [];
let mouse = {x:W/2, y:H/3, down:false};
let drawT = 0;           // 0..1 bow draw while holding
let shake = 0;
let time = 0;

const archer = { x:110, y:H-70 };

function rand(a,b){ return a + Math.random()*(b-a); }

function spawnBalloon(){
  const r = rand(20,30);
  balloons.push({
    x: rand(320, W-60),
    y: H + r + 10,
    r,
    vy: -rand(40, 75),
    sway: rand(0, Math.PI*2),
    swaySpd: rand(0.8,1.6),
    hue: [0,35,55,120,200,260,320][Math.floor(Math.random()*7)],
    alive: true
  });
}

function reset(){
  score = 0; shots = 0;
  balloons = []; arrows = []; parts = []; floats = [];
  for(let i=0;i<5;i++){ spawnBalloon(); balloons[i].y = rand(80, H-140); }
  state = STATE.PLAY;
}

/* ---------- input ---------- */
function canvasPos(e){
  const r = cv.getBoundingClientRect();
  return { x:(e.clientX-r.left)*W/r.width, y:(e.clientY-r.top)*H/r.height };
}
cv.addEventListener('mousemove', e=>{ const p=canvasPos(e); mouse.x=p.x; mouse.y=p.y; });
